import{_ as a,c as s,o as e,ag as n}from"./chunks/framework.0-OC-noK.js";const k=JSON.parse('{"title":"Getting Started","description":"Installation and initial setup for Kirox CLI","frontmatter":{"title":"Getting Started","description":"Installation and initial setup for Kirox CLI"},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),t={name:"guide/getting-started.md"};function l(r,i,o,p,h,d){return e(),s("div",null,[...i[0]||(i[0]=[n(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>This guide explains how to get started with Kirox CLI.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>To use Kirox CLI, you need the following environment:</p><ul><li><strong>Node.js 18.0.0 or higher</strong>: Download from <a href="https://nodejs.org/" target="_blank" rel="noreferrer">Node.js official website</a></li><li><strong>npm 9 or higher</strong>: Included with Node.js</li><li><strong>Git</strong>: Version control tool (optional)</li></ul><p>Verify versions:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # v18.0.0 or higher</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 9.0.0 or higher</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Kirox CLI <strong>does not require global installation</strong> and can be run immediately with the npx command.</p><h3 id="run-with-npx-recommended" tabindex="-1">Run with npx (Recommended) <a class="header-anchor" href="#run-with-npx-recommended" aria-label="Permalink to &quot;Run with npx (Recommended)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kirox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> owner/repo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project-name</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This method is recommended as it always runs the latest version.</p><h3 id="global-installation" tabindex="-1">Global Installation <a class="header-anchor" href="#global-installation" aria-label="Permalink to &quot;Global Installation&quot;">​</a></h3><p>If you use it frequently, you can install it globally:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kirox</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> owner/repo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project-name</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="first-run" tabindex="-1">First Run <a class="header-anchor" href="#first-run" aria-label="Permalink to &quot;First Run&quot;">​</a></h2><h3 id="basic-usage" tabindex="-1">Basic Usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic Usage&quot;">​</a></h3><p>Fetch specifications from a GitHub repository:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kirox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yukihirop/my-project</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-spec</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="interactive-mode" tabindex="-1">Interactive Mode <a class="header-anchor" href="#interactive-mode" aria-label="Permalink to &quot;Interactive Mode&quot;">​</a></h3><p>Running without options allows you to configure interactively:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kirox</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Follow the prompts to enter:</p><ol><li>GitHub repository (e.g., <code>yukihirop/my-project</code>)</li><li>Branch (optional)</li><li>Subdirectory (optional)</li><li>Project name (multiple selection available)</li></ol><h2 id="github-authentication-optional" tabindex="-1">GitHub Authentication (Optional) <a class="header-anchor" href="#github-authentication-optional" aria-label="Permalink to &quot;GitHub Authentication (Optional)&quot;">​</a></h2><p>To access private repositories or to relax GitHub API rate limits, set up a Personal Access Token (PAT).</p><h3 id="obtaining-a-pat" tabindex="-1">Obtaining a PAT <a class="header-anchor" href="#obtaining-a-pat" aria-label="Permalink to &quot;Obtaining a PAT&quot;">​</a></h3><ol><li>Go to <a href="https://github.com/settings/tokens" target="_blank" rel="noreferrer">GitHub Settings → Developer settings → Personal access tokens</a></li><li>Click &quot;Generate new token (classic)&quot;</li><li>Select the following scopes: <ul><li><code>public_repo</code>: Read public repositories</li><li><code>repo</code>: Read private repositories (if needed)</li></ul></li><li>Generate and copy the token</li></ol><h3 id="setting-environment-variables" tabindex="-1">Setting Environment Variables <a class="header-anchor" href="#setting-environment-variables" aria-label="Permalink to &quot;Setting Environment Variables&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS / Linux</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GITHUB_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ghp_your_token_here</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows (PowerShell)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:GITHUB_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ghp_your_token_here&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>To set permanently, add to <code>.bashrc</code>, <code>.zshrc</code>, or <code>.profile</code>:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;export GITHUB_TOKEN=ghp_your_token_here&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bashrc</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bashrc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Verify that Kirox CLI is working correctly with the following command:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kirox</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>If the help message is displayed, the installation was successful.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/kirox/guide/basic-usage.html">Basic Usage</a>: Details on commands and options</li><li><a href="/kirox/guide/advanced-usage.html">Advanced Usage</a>: Configuration files and advanced features</li><li><a href="/kirox/cli/">CLI Reference</a>: Reference for all commands</li></ul>`,38)])])}const u=a(t,[["render",l]]);export{k as __pageData,u as default};
